from PIL import Image
im = Image.open('/home/robot/captures/top_007.png')
w,h=im.size
px=im.load()
# classify pixels
# orange base, blue tray, white pins
orange=[]; blue=[]; bright=[]
for y in range(h):
    for x in range(w):
        r,g,b=px[x,y][:3]
        if r>140 and g>70 and g<140 and b<80:
            orange.append((x,y))
        if b>r+25 and b>g+10 and b>90 and r<120:
            blue.append((x,y))
        if r>190 and g>190 and b>180:
            bright.append((x,y))
def bbox(pts, name):
    if not pts:
        print(name, 'none'); return
    xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
    print(name, 'n', len(pts), 'bbox', min(xs), min(ys), max(xs), max(ys), 'centroid', sum(xs)/len(xs), sum(ys)/len(ys))
bbox(orange,'orange')
bbox(blue,'blue')
bbox(bright,'bright')
# show a downsampled color-coded map
print('MAP O=orange B=blue W=white .=table #=dark')
for gy in range(24):
    y=int((gy+0.5)*h/24)
    row=[]
    for gx in range(32):
        x=int((gx+0.5)*w/32)
        r,g,b=px[x,y][:3]
        v=(r+g+b)/3
        if r>140 and g>70 and b<90:
            row.append('O')
        elif b>r+20 and b>100:
            row.append('B')
        elif v>180:
            row.append('W')
        elif v<50:
            row.append('#')
        elif v<100:
            row.append('+')
        else:
            row.append('.')
    print(f"{y:3d} {''.join(row)}")
